DROP TRIGGER version_state_machine;
CREATE TRIGGER version_state_machine BEFORE UPDATE OF state ON asset_version WHEN OLD.state!=NEW.state AND NOT ((OLD.state='draft' AND NEW.state IN ('submitted','withdrawn')) OR (OLD.state='submitted' AND NEW.state IN ('processing','withdrawn')) OR (OLD.state='processing' AND NEW.state IN ('submitted','changes_requested','awaiting_review','rejected','withdrawn')) OR (OLD.state='awaiting_review' AND NEW.state IN ('changes_requested','rejected','approved','withdrawn')) OR (OLD.state='changes_requested' AND NEW.state IN ('submitted','withdrawn')) OR (OLD.state='rejected' AND NEW.state IN ('awaiting_review','withdrawn')) OR (OLD.state='approved' AND NEW.state IN ('published','withdrawn')) OR (OLD.state='published' AND NEW.state='withdrawn')) BEGIN SELECT RAISE(ABORT,'invalid_version_transition'); END;
CREATE TABLE safety_policy(id TEXT PRIMARY KEY,version TEXT NOT NULL UNIQUE CHECK(length(version) BETWEEN 1 AND 60),thresholds TEXT NOT NULL CHECK(json_valid(thresholds)),detectors TEXT NOT NULL CHECK(json_valid(detectors)),enforce INTEGER NOT NULL DEFAULT 0 CHECK(enforce IN (0,1)),enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),created_at INTEGER NOT NULL);
CREATE TRIGGER safety_policy_immutable BEFORE UPDATE OF id,version,thresholds,detectors,enforce,created_at ON safety_policy BEGIN SELECT RAISE(ABORT,'safety_policy_immutable'); END;
CREATE TRIGGER safety_policy_no_delete BEFORE DELETE ON safety_policy BEGIN SELECT RAISE(ABORT,'safety_policy_immutable'); END;
CREATE TRIGGER safety_policy_epoch AFTER INSERT ON safety_policy BEGIN UPDATE authority_policy SET epoch=epoch+1 WHERE id=1; END;
CREATE TRIGGER safety_policy_disable_epoch AFTER UPDATE OF enabled ON safety_policy WHEN OLD.enabled!=NEW.enabled BEGIN UPDATE authority_policy SET epoch=epoch+1 WHERE id=1; END;
INSERT INTO safety_policy(id,version,thresholds,detectors,enforce,enabled,created_at) VALUES('sp-v1-shadow','safety-v1.0-shadow','{"version":"safety-v1.0-shadow","enforce":false,"maxImages":400,"flag":{"sexual":0.4,"hate_symbol":0.4,"violence":0.5,"child_like":0.4,"child_like_sexual":0.3},"reject":{"sexual_single":0.95,"sexual_multi":0.85,"sexual_multi_count":2,"hate_symbol":0.9,"child_like":0.5,"child_like_sexual":0.6},"text":{"severe":"reject","context":"flag"},"hiddenGeometry":"flag","tinyIslands":"low","suspiciousInstructions":"flag","llm":"stricter_only"}','["render-v1","nsfw-stub-v1","child-like-stub-v1","hate-symbol-template-v1","ocr-tesseract-v1","text-wordlist-v1","instruction-scan-v1","geometry-visibility-v1","llm-second-opinion-v1"]',0,1,0);
CREATE TABLE safety_canary_run(id TEXT PRIMARY KEY,processor_id TEXT NOT NULL REFERENCES processor(id),policy_version TEXT NOT NULL,detectors_hash TEXT NOT NULL CHECK(length(detectors_hash)=64),passed INTEGER NOT NULL CHECK(passed IN (0,1)),detail TEXT NOT NULL CHECK(json_valid(detail) AND length(detail)<=20000),created_at INTEGER NOT NULL);
CREATE INDEX safety_canary_latest ON safety_canary_run(policy_version,detectors_hash,created_at);
CREATE TRIGGER safety_canary_append_only BEFORE UPDATE ON safety_canary_run BEGIN SELECT RAISE(ABORT,'safety_canary_append_only'); END;
CREATE TRIGGER safety_canary_no_delete BEFORE DELETE ON safety_canary_run BEGIN SELECT RAISE(ABORT,'safety_canary_append_only'); END;
CREATE TABLE safety_attempt(id TEXT PRIMARY KEY,upload_id TEXT NOT NULL REFERENCES uploads(id),processor_id TEXT NOT NULL REFERENCES processor(id),claim_key TEXT NOT NULL,lease_hash TEXT NOT NULL CHECK(length(lease_hash)=64),lease_expires_at INTEGER NOT NULL,policy_version TEXT NOT NULL,detectors_hash TEXT NOT NULL,report_id TEXT REFERENCES safety_report(id),created_at INTEGER NOT NULL,UNIQUE(processor_id,claim_key));
CREATE INDEX safety_attempt_upload ON safety_attempt(upload_id,created_at);
CREATE TRIGGER safety_attempt_identity BEFORE UPDATE OF id,upload_id,processor_id,claim_key,lease_hash,policy_version,detectors_hash,created_at ON safety_attempt BEGIN SELECT RAISE(ABORT,'safety_attempt_immutable'); END;
CREATE TRIGGER safety_attempt_report_once BEFORE UPDATE OF report_id ON safety_attempt WHEN OLD.report_id IS NOT NULL BEGIN SELECT RAISE(ABORT,'safety_attempt_immutable'); END;
CREATE TRIGGER safety_attempt_no_delete BEFORE DELETE ON safety_attempt BEGIN SELECT RAISE(ABORT,'safety_attempt_immutable'); END;
CREATE TABLE safety_artifact(attempt_id TEXT NOT NULL REFERENCES safety_attempt(id),name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 100),object_key TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL CHECK(length(sha256)=64),bytes INTEGER NOT NULL CHECK(bytes>0 AND bytes<=2097152),media_type TEXT NOT NULL CHECK(media_type IN ('image/png','image/jpeg')),created_at INTEGER NOT NULL,PRIMARY KEY(attempt_id,name));
CREATE TRIGGER safety_artifact_immutable BEFORE UPDATE ON safety_artifact BEGIN SELECT RAISE(ABORT,'safety_artifact_immutable'); END;
CREATE TRIGGER safety_artifact_no_delete BEFORE DELETE ON safety_artifact BEGIN SELECT RAISE(ABORT,'safety_artifact_immutable'); END;
ALTER TABLE uploads ADD COLUMN scan_attempts INTEGER NOT NULL DEFAULT 0;
CREATE TABLE version_auto_rejection(version_id TEXT PRIMARY KEY REFERENCES asset_version(id),report_id TEXT NOT NULL UNIQUE REFERENCES safety_report(id),created_at INTEGER NOT NULL);
CREATE TRIGGER version_auto_rejection_needs_report BEFORE INSERT ON version_auto_rejection WHEN NOT EXISTS(SELECT 1 FROM safety_report r WHERE r.id=NEW.report_id AND r.version_id=NEW.version_id AND r.outcome='reject' AND r.shadow=0) BEGIN SELECT RAISE(ABORT,'auto_reject_requires_report'); END;
CREATE TRIGGER version_auto_rejection_immutable BEFORE UPDATE ON version_auto_rejection BEGIN SELECT RAISE(ABORT,'version_auto_rejection_immutable'); END;
CREATE TRIGGER version_auto_rejection_no_delete BEFORE DELETE ON version_auto_rejection BEGIN SELECT RAISE(ABORT,'version_auto_rejection_immutable'); END;
CREATE TRIGGER processing_reject_is_auto BEFORE UPDATE OF state ON asset_version WHEN OLD.state='processing' AND NEW.state='rejected' AND NOT EXISTS(SELECT 1 FROM version_auto_rejection a WHERE a.version_id=NEW.id) BEGIN SELECT RAISE(ABORT,'auto_reject_requires_report'); END;
CREATE TRIGGER rejected_auto_appeal_by_human BEFORE UPDATE OF state ON asset_version WHEN OLD.state='rejected' AND NEW.state='awaiting_review' AND (NOT EXISTS(SELECT 1 FROM version_auto_rejection a WHERE a.version_id=NEW.id) OR NOT EXISTS(SELECT 1 FROM queue_event_log e JOIN capability c ON c.user_id=e.actor_id AND c.name IN ('moderator','admin') WHERE e.version_id=NEW.id AND e.kind='override' AND json_extract(e.detail,'$.outcome')='appeal_accepted')) BEGIN SELECT RAISE(ABORT,'appeal_requires_moderator'); END;
CREATE TRIGGER approval_requires_safety_clearance BEFORE UPDATE OF state ON asset_version WHEN NEW.state='approved' AND OLD.state!='approved' AND (SELECT r.outcome FROM safety_report r WHERE r.version_id=NEW.id ORDER BY r.created_at DESC,r.rowid DESC LIMIT 1)='reject' AND NOT EXISTS(SELECT 1 FROM queue_event_log e JOIN capability c ON c.user_id=e.actor_id AND c.name IN ('moderator','admin') WHERE e.version_id=NEW.id AND e.kind='override' AND json_extract(e.detail,'$.outcome')='clean') BEGIN SELECT RAISE(ABORT,'safety_clearance_required'); END;
